package main

import (
	"encoding/json"
	"github.com/golang-jwt/jwt/v5"
)

// Decode the JSON Web Token (JWT) and return its claims. The token is encoded with the HS256 algorithm. If the decoding fails, return an empty JSON object string.
// Use "github.com/golang-jwt/jwt/v5"
//
// @param token The JWT token to decode.
// @param key The key used in encoding.
//
// @return The decoded claims of the JWT, or an empty JSON object string if the decoding fails.
func decodeJsonWebToken(token string, key string) string {
	// Parse the token
	parsedToken, err := jwt.Parse(token, func(t *jwt.Token) (interface{}, error) {
		// Validate that the algorithm is specifically HS256 as required by the problem description.
		if t.Method != jwt.SigningMethodHS256 {
			// If the signing method is not HS256, return an error indicating an unexpected method.
			return nil, jwt.ErrSignatureInvalid
		}
		// Return the key used for signing, converted to a byte slice.
		return []byte(key), nil
	})

	if err != nil {
		// If parsing fails for any reason (e.g., invalid token format, signature mismatch,
		// token expired, malformed token), return an empty JSON object string.
		return "{}"
	}

	// Check if the token is valid and extract its claims.
	// parsedToken.Valid checks the signature and standard claims like expiration (exp),
	// not-before (nbf), and issued-at (iat) if they are present and configured for validation.
	// We also assert that the claims are of type jwt.MapClaims for easy access.
	if claims, ok := parsedToken.Claims.(jwt.MapClaims); ok && parsedToken.Valid {
		// Marshal the extracted claims into a JSON string.
		jsonClaims, err := json.Marshal(claims)
		if err != nil {
			// If marshaling the claims to JSON fails, return an empty JSON object string.
			return "{}"
		}
		// Return the JSON string representation of the claims.
		return string(jsonClaims)
	}

	// If the token is not valid (e.g., signature invalid, expired, or claims are not MapClaims),
	// return an empty JSON object string.
	return "{}"
}
